import{_ as e,o as a,c as o,ag as d}from"./chunks/framework.Pp2klvcf.js";const h=JSON.parse('{"title":"Content, portal, comments, and payments","description":"","frontmatter":{},"headers":[],"relativePath":"en/server/api/content-portal.md","filePath":"en/server/api/content-portal.md","lastUpdated":1788681727000}'),n={name:"en/server/api/content-portal.md"};function c(r,t,i,s,p,l){return a(),o("div",null,[...t[0]||(t[0]=[d('<h1 id="content-portal-comments-and-payments" tabindex="-1">Content, portal, comments, and payments <a class="header-anchor" href="#content-portal-comments-and-payments" aria-label="Permalink to &quot;Content, portal, comments, and payments&quot;">​</a></h1><h2 id="content-management" tabindex="-1">Content management <a class="header-anchor" href="#content-management" aria-label="Permalink to &quot;Content management&quot;">​</a></h2><p>Authenticated admin applications use REST CRUD at <code>/api/v1/content/articles</code> and <code>/api/v1/content/categories</code>. Article listing accepts <code>page</code>, <code>pageSize</code>, <code>keyword</code>, <code>categoryId</code>, and <code>status</code>.</p><h2 id="public-site-reads" tabindex="-1">Public site reads <a class="header-anchor" href="#public-site-reads" aria-label="Permalink to &quot;Public site reads&quot;">​</a></h2><p>No login or Bearer token is required for:</p><table tabindex="0"><thead><tr><th>Method and path</th><th>Purpose</th></tr></thead><tbody><tr><td>GET <code>/api/v1/public/home</code></td><td>Homepage content</td></tr><tr><td>GET <code>/api/v1/public/features</code>, <code>/product</code></td><td>Product content</td></tr><tr><td>GET <code>/api/v1/public/pricing</code></td><td>Pricing plans</td></tr><tr><td>GET <code>/api/v1/public/blog</code>, <code>/blog/{id}</code></td><td>Blog list and article</td></tr><tr><td>GET <code>/api/v1/public/blog/{id}/comments</code></td><td>Published comments</td></tr><tr><td>GET <code>/api/v1/public/faq</code>, <code>/docs</code>, <code>/about</code></td><td>Help and company content</td></tr><tr><td>POST <code>/api/v1/public/contact</code></td><td>Contact form</td></tr></tbody></table><h2 id="authenticated-interactions" tabindex="-1">Authenticated interactions <a class="header-anchor" href="#authenticated-interactions" aria-label="Permalink to &quot;Authenticated interactions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method and path</th><th>Purpose</th></tr></thead><tbody><tr><td>POST <code>/api/v1/blog/{id}/comments</code></td><td>Create a comment as the signed-in user</td></tr><tr><td>POST <code>/api/v1/payments/checkout</code></td><td>Create a pending pricing order</td></tr></tbody></table><p>Anonymous writes return HTTP 401. Checkout accepts <code>planId</code> and <code>channel</code> (<code>alipay</code>, <code>wechat</code>, or <code>card</code>) and returns an order number, amount, expiry, and demo checkout URL. Migration <code>V7__site_interactions.sql</code> persists both comments and payment orders.</p><p>The frontend keeps pricing and blog routes public. It redirects to <code>/login?redirect=...</code> only when a visitor submits a comment or starts checkout, then returns to the original page after login.</p>',10)])])}const u=e(n,[["render",c]]);export{h as __pageData,u as default};
